import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.listing.*;
public class ShapeMaterializeEvidence extends GhidraScript { public void run()throws Exception{DecompInterface d=new DecompInterface();d.openProgram(currentProgram);long[] xs={0x004D64C0L,0x004D6560L,0x0041A2D0L,0x00425A70L};for(long x:xs){Function f=getFunctionAt(toAddr(x));println("\n=== "+toAddr(x)+" "+(f==null?"<missing>":f.getName())+" ===");if(f!=null){DecompileResults r=d.decompileFunction(f,700,monitor);if(r.getDecompiledFunction()!=null)println(r.getDecompiledFunction().getC());}}d.dispose();}}
